-- 기존 현업자 회사 이름을 회사로 옮김. 정규화(normalizeCompanyName, src/company/company.utils.ts)가 같은 이름끼리 한 회사로 묶고,
-- 회사 이름은 그중 가장 먼저 저장된 원문. 어드민이 확인하도록 needs_review = true
INSERT INTO "company_alias" ("name", "needs_review")
SELECT DISTINCT ON (lower(regexp_replace(regexp_replace(normalize("company", NFC), '^\s+|\s+$', '', 'g'), '\s+', ' ', 'g'))) regexp_replace(normalize("company", NFC), '^\s+|\s+$', '', 'g'), true
FROM "graduated_profile"
ORDER BY lower(regexp_replace(regexp_replace(normalize("company", NFC), '^\s+|\s+$', '', 'g'), '\s+', ' ', 'g')), "created_at", "graduated_pk";--> statement-breakpoint
INSERT INTO "company_name" ("alias_pk", "name", "normalized_name")
SELECT "pk", "name", lower(regexp_replace(regexp_replace(normalize("name", NFC), '^\s+|\s+$', '', 'g'), '\s+', ' ', 'g')) FROM "company_alias";--> statement-breakpoint
UPDATE "graduated_profile" SET "company_alias_pk" = cn."alias_pk"
FROM "company_name" cn
WHERE cn."normalized_name" = lower(regexp_replace(regexp_replace(normalize("graduated_profile"."company", NFC), '^\s+|\s+$', '', 'g'), '\s+', ' ', 'g'));
